console.log(classifyAge(64));   // "adult"
console.log(classifyAge(65));   // "senior"
console.log(classifyAge(0));    // "child"

// Invalid inputs
try { classifyAge(-1); }       catch (e) { console.error(e.message); } // Age cannot be negative, received: -1
try { classifyAge("30"); }     catch (e) { console.error(e.message); } // Age must be a finite number, received: 30
