```javascript
function classifyAge(age) {
  if (typeof age !== "number" || !Number.isFinite(age) || age < 0) {
    throw new Error("Age must be a non-negative finite number.");
  }

  if (age < 13) return "child";
  if (age < 20) return "teen";
  if (age < 65) return "adult";
  return "senior";
}
```

