## Implementation

```js
function classifyAge(age) {
  // Reject non-numeric types (strings, null, undefined, booleans, objects...)
  if (typeof age !== "number") {
    throw new TypeError(`Age must be a number, received ${typeof age}`);
  }

  // Reject NaN and Infinity/-Infinity
  if (!Number.isFinite(age)) {
    throw new TypeError("Age must be a finite number");
  }

  // Reject negative values
  if (age < 0) {
    throw new RangeError("Age cannot be negative");
  }

  if (age < 13) return "child";
  if (age < 20) return "teen";
  if (age < 65) return "adult";
  return "senior";
}
```

