```js
/**
 * Maps an HTTP status code to its class family.
 *
 * @param {number} code - An integer status code in the range 100..599.
 * @returns {"info"|"success"|"redirect"|"client-error"|"server-error"}
 * @throws {TypeError}  If `code` is not an integer.
 * @throws {RangeError} If `code` is outside 100..599.
 */
function httpStatusBucket(code) {
  if (!Number.isInteger(code)) {
    throw new TypeError(`Status code must be an integer, got: ${code}`);
  }
  if (code < 100 || code > 599) {
    throw new RangeError(`Status code must be between 100 and 599, got: ${code}`);
  }

  switch (Math.floor(code / 100)) {
    case 1: return "info";
    case 2: return "success";
    case 3: return "redirect";
    case 4: return "client-error";
    case 5: return "server-error";
    default: // unreachable given the range check
      throw new RangeError(`Status code must be between 100 and 599, got: ${code}`);
  }
}
```

### Examples

```js
httpStatusBucket(100); // "info"
httpStatusBucket(204); // "success"
httpStatusBucket(301); // "redirect"
httpStatusBucket(404); // "client-error"
httpStatusBucket(503); // "server-error"

httpStatusBucket(99);   // throws RangeError
httpStatusBucket(600);  // throws RangeError
httpStatusBucket(200.5);// throws TypeError
httpStatusBucket("200");// throws TypeError
```

### Notes

- **Integer check first:** `Number.isInteger` rejects `200.5`, `"200"`, `NaN`, and `Infinity`, so the range check can't be fooled by non-numeric input.
- **Range check second:** `100` and `599` are inclusive; `99` and `600` are rejected.
- **Why `Math.floor(code / 100)`:** it buckets by the leading digit, so `200`–`299` all land in the same family.

