- If you'd prefer invalid input to return `null` or `undefined` instead of throwing, swap the `throw` for a `return null`.

```js
/**
 * Buckets an HTTP status code into its class.
 *
 * @param {number} code - An integer status code in the range 100..599.
 * @returns {"info"|"success"|"redirect"|"client-error"|"server-error"}
 * @throws {TypeError}  If `code` is not an integer number.
 * @throws {RangeError} If `code` is outside 100..599.
 */
function httpStatusBucket(code) {
  if (typeof code !== "number" || !Number.isInteger(code)) {
    throw new TypeError(`Status code must be an integer, got ${JSON.stringify(code)}`);
  }
  if (code < 100 || code > 599) {
    throw new RangeError(`Status code out of range: ${code} (expected 100-599)`);
  }

  switch (Math.floor(code / 100)) {
    case 1: return "info";
    case 2: return "success";
    case 3: return "redirect";
    case 4: return "client-error";
    case 5: return "server-error";
    /* c8 ignore next */
    default: throw new RangeError(`Unrecognized status code: ${code}`);
  }
}
```

